<?php require __DIR__.'/config.php'; $username=trim($_GET['u']??''); $pdo=db(); $st=$pdo->prepare('SELECT p.*,u.id user_id,u.username,u.name FROM profiles p JOIN users u ON u.id=p.user_id WHERE u.username=? AND u.is_active=1 AND p.is_published=1 LIMIT 1');$st->execute([$username]);$p=$st->fetch(); if(!$p){http_response_code(404);exit('Profile not found');}$pdo->prepare('UPDATE profiles SET views_count=views_count+1 WHERE id=?')->execute([$p['id']]);$ls=$pdo->prepare('SELECT * FROM links WHERE user_id=? AND is_active=1 ORDER BY position,id');$ls->execute([$p['user_id']]);$links=$ls->fetchAll();?><!doctype html><html lang="<?=lang()?>" dir="<?=dir_attr()?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($p['title']?:$p['name'])?> · <?=APP_NAME?></title><link rel="stylesheet" href="assets/style.css"><style>body{min-height:100vh;background:linear-gradient(155deg,#dfe8ff,#f8faff)}.public-page{width:min(620px,92%);margin:auto;padding:60px 0}.public-card{text-align:center}.public-link{display:block;background:#fff;border:1px solid rgba(255,255,255,.8);border-radius:18px;padding:17px 20px;margin:13px 0;font-weight:900;box-shadow:0 12px 28px rgba(52,68,110,.09);transition:.2s}.public-link:hover{transform:translateY(-2px)}.mini-brand{text-align:center;color:#6d7890;margin-top:28px;font-weight:800}</style></head><body><main class="public-page"><div class="public-card"><div class="avatar"><?=e(mb_strtoupper(mb_substr($p['name'],0,1)))?></div><h1><?=e($p['title']?:$p['name'])?></h1><p class="muted"><?=e($p['bio'])?></p><?php foreach($links as $link):?><a class="public-link" href="click.php?id=<?=$link['id']?>" rel="noopener noreferrer"><?=e($link['title'])?></a><?php endforeach;?><div class="mini-brand">Linkiraq</div></div></main></body></html>